def enable_rls() -> None:
    """Defense in depth for Supabase.

    The frontend only uses Supabase for auth, but the anon key is public, so the
    auto-generated Data API must not expose these tables. RLS is enabled with no
    policies (= deny all for anon/authenticated) and their grants are revoked.
    The API connects as the table owner, which bypasses RLS, and enforces
    per-user access itself (every query is filtered by user_id).
    """
    for table in TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
    op.execute(
        """
        DO $$
        DECLARE t text;
        BEGIN
          IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
            FOREACH t IN ARRAY ARRAY[%s] LOOP
              EXECUTE format('REVOKE ALL ON TABLE %%I FROM anon, authenticated', t);
            END LOOP;
          END IF;
        END $$;
        """  # noqa: UP031 - %%I must reach Postgres' format() intact
        % ", ".join(f"'{t}'" for t in TABLES)
    )


